  Reset(p);p->colorFilterFormAudit_=[](FormDialog& f){f.Fields()[0].value=L"0";return IDOK;};check(Reject([&]{p->ColorFilterCommand(ColorGamma);})&&!p->screenColorModal_&&!p->job_.Busy(),"invalid injected form resets modal guard without opening generic error dialogs");
